public void calcDepthRec() {
            if (next.isEmpty()) {
                this.followingDepth = 0;
            } else {
                for (LightningVertex vertex : next) {
                    vertex.calcDepthRec();
                }
                this.followingDepth = MiscUtils.getMaxEntry(this.next, (v) -> v.followingDepth) + 1;
            }
        }

