        if ((revealTicks - fadeTicks) < 0) {
            if (alphaReveal > 0) {
                alphaReveal = Math.max(0, alphaReveal - visibilityChange);
            }
        } else {
            if (alphaReveal < 1) {
                alphaReveal = Math.min(1, alphaReveal + visibilityChange);
            }
        }
    }

