public RenderAltar(TileEntityRendererDispatcher tileRenderer) {
        super(tileRenderer);
    }

@Override
    public void render(TileAltar tile, float pTicks, MatrixStack renderStack, IRenderTypeBuffer renderTypeBuffer, int combinedLight, int combinedOverlay) {
        if (tile.getAltarType().isThisGEThan(AltarType.RADIANCE) && tile.hasMultiblock()) {
            IConstellation cst = tile.getFocusedConstellation();
            if (cst != null) {
                float dayAlpha = DayTimeHelper.getCurrentDaytimeDistribution(tile.getWorld()) * 0.6F;

                int max = 3000;
                int t = (int) (ClientScheduler.getClientTick() % max);
                float halfAge = max / 2F;
                float tr = 1F - (Math.abs(halfAge - t) / halfAge);
                tr *= 1.3;

                RenderingConstellationUtils.renderConstellationIntoWorldFlat(
                        cst, renderStack, renderTypeBuffer,
                        new Vector3(0.5, 0.03, 0.5),
                        5.5 + tr,
                        2,
                        0.1F + dayAlpha);
            }
        }

        ActiveSimpleAltarRecipe recipe = tile.getActiveRecipe();
        if (recipe != null) {
            recipe.getRecipeToCraft().getCraftingEffects()
                    .forEach(effect -> effect.onTESR(tile, recipe.getState(), renderStack, renderTypeBuffer, pTicks, combinedLight));
        }

        if (tile.getAltarType().isThisGEThan(AltarType.RADIANCE) && tile.hasMultiblock()) {
            renderStack.push();
            renderStack.translate(0.5F, 4.5F, 0.5F);

            long id = tile.getPos().toLong();
            if (recipe != null) {
                List<WrappedIngredient> traitInputs = recipe.getRecipeToCraft().getRelayInputs();
                if (!traitInputs.isEmpty()) {
                    int amount = 60 / traitInputs.size();
                    for (int i = 0; i < traitInputs.size(); i++) {
                        WrappedIngredient ingredient = traitInputs.get(i);
                        ItemStack traitInput = ingredient.getRandomMatchingStack(ClientScheduler.getClientTick());
                        Color color = ColorizationHelper.getColor(traitInput).orElse(ColorsAS.CELESTIAL_CRYSTAL);

                        RenderingDrawUtils.renderLightRayFan(renderStack, renderTypeBuffer, color, 0x1231943167156902L | id | (i * 0x5151L), 20, 2F, amount);
                    }
                } else {
                    RenderingDrawUtils.renderLightRayFan(renderStack, renderTypeBuffer, Color.WHITE, id * 31L, 15, 1.5F, 35);
                    RenderingDrawUtils.renderLightRayFan(renderStack, renderTypeBuffer, ColorsAS.CELESTIAL_CRYSTAL, id * 16L, 10, 1F, 25);
                }
                RenderingDrawUtils.renderLightRayFan(renderStack, renderTypeBuffer, Color.WHITE, id * 31L, 10, 1F, 10);
            } else {
                RenderingDrawUtils.renderLightRayFan(renderStack, renderTypeBuffer, Color.WHITE, id * 31L, 15, 1.5F, 35);
                RenderingDrawUtils.renderLightRayFan(renderStack, renderTypeBuffer, ColorsAS.CELESTIAL_CRYSTAL, id * 16L, 10, 1F, 25);
            }

            renderStack.pop();
        }
    }

public RenderAttunementAltar(TileEntityRendererDispatcher tileRenderer) {
        super(tileRenderer);
    }

@Override
    public void render(TileAttunementAltar tile, float pTicks, MatrixStack renderStack, IRenderTypeBuffer renderTypeBuffer, int combinedLight, int combinedOverlay) {
        renderStack.push();
        renderStack.translate(0.5, 0.5, 0.5);
        renderStack.rotate(Vector3f.XP.rotationDegrees(180));
        MODEL_ATTUNEMENT_ALTAR.render(renderStack, renderTypeBuffer, combinedLight, combinedOverlay);
        renderStack.pop();

        float spinDur = TileAttunementAltar.MAX_START_ANIMATION_SPIN;
        float spinStart = TileAttunementAltar.MAX_START_ANIMATION_TICK;

        float startY = -1.2F;
        float endY   = -0.5F;
        float tickPartY = (endY - startY) / spinStart;
        float prevPosY = endY + (tile.prevActivationTick * tickPartY);
        float posY     = endY + (tile.activationTick     * tickPartY);
        float framePosY = RenderingVectorUtils.interpolate(prevPosY, posY, pTicks);

        double generalAnimationTick = (ClientScheduler.getClientTick() + pTicks) / 4D;
        if (tile.animate) {
            if (tile.tesrLocked) {
                tile.tesrLocked = false;
            }
        } else {
            if (tile.tesrLocked) {
                generalAnimationTick = 7.25D;
            } else {
                if (Math.abs((generalAnimationTick % spinDur) - 7.25D) <= 0.3125) {
                    generalAnimationTick = 7.25D;
                    tile.tesrLocked = true;
                }
            }
        }

        for (int i = 1; i < 9; i++) {
            float incrementer = (spinDur / 8F) * i;

            double aFrame =     generalAnimationTick + incrementer;
            double prevAFrame = generalAnimationTick + incrementer - 1;
            double renderFrame = RenderingVectorUtils.interpolate(prevAFrame, aFrame, 0);

            double partRenderFrame = (renderFrame % spinDur) / spinDur;
            float normalized = (float) (partRenderFrame * 2F * Math.PI);

            float xOffset = MathHelper.cos(normalized);
            float zOffset = MathHelper.sin(normalized);
            float rotation = RenderingVectorUtils.interpolate(tile.prevActivationTick / spinStart, tile.activationTick / spinStart, pTicks);

            renderStack.push();
            renderStack.translate(0.5, framePosY, 0.5);
            renderStack.rotate(Vector3f.XP.rotationDegrees(180));
            MODEL_ATTUNEMENT_ALTAR.renderHovering(renderStack, renderTypeBuffer.getBuffer(MODEL_ATTUNEMENT_ALTAR.getGeneralType()), combinedLight, combinedOverlay, 1F, 1F, 1F, 1F, xOffset, zOffset, rotation);
            renderStack.pop();
        }
    }

public RenderChalice(TileEntityRendererDispatcher tileRenderer) {
        super(tileRenderer);
    }

@Override
    public void render(TileChalice tile, float pTicks, MatrixStack renderStack, IRenderTypeBuffer renderTypeBuffer, int combinedLight, int combinedOverlay) {
        FluidStack stack = tile.getTank().getFluid();
        if (stack.isEmpty()) {
            return;
        }
        TextureAtlasSprite tas = RenderingUtils.getParticleTexture(stack);
        if (tas == null) {
            return;
        }

        Vector3 rotation = RenderingVectorUtils.interpolate(tile.getPrevRotation(), tile.getRotation(), pTicks);
        Color color = new Color(ColorUtils.getOverlayColor(stack));
        float percSize = 0.125F + (tile.getTank().getPercentageFilled() * 0.375F);

        float ulength = tas.getMaxU() - tas.getMinU();
        float vlength = tas.getMaxV() - tas.getMinV();

        float uPart = ulength * percSize;
        float vPart = vlength * percSize;
        float uOffset = tas.getMinU() + ulength / 2F - uPart / 2F;
        float vOffset = tas.getMinV() + vlength / 2F - vPart / 2F;

        renderStack.push();
        renderStack.translate(0.5F, 1.4F, 0.5F);
        renderStack.rotate(Vector3f.XP.rotationDegrees((float) rotation.getX()));
        renderStack.rotate(Vector3f.YP.rotationDegrees((float) rotation.getY()));
        renderStack.rotate(Vector3f.ZP.rotationDegrees((float) rotation.getZ()));
        renderStack.scale(percSize, percSize, percSize);

        IVertexBuilder buf = renderTypeBuffer.getBuffer(RenderTypesAS.TER_CHALICE_LIQUID);
        RenderingDrawUtils.renderTexturedCubeCentralColorNormal(renderStack, buf,
                uOffset, vOffset, uPart, vPart,
                color.getRed(), color.getGreen(), color.getBlue(), 255,
                renderStack.getLast().getNormal());

        renderStack.pop();
    }

