@Nullable
    public static MMCQ.CMap getColorMap(BufferedImage sourceImage, int colorCount, int quality, boolean ignoreWhite) {
        int[][] pixelArray;

        switch (sourceImage.getType()) {
            case BufferedImage.TYPE_3BYTE_BGR:
            case BufferedImage.TYPE_4BYTE_ABGR:
                pixelArray = getPixelsFast(sourceImage, quality, ignoreWhite);
                break;

            default:
                pixelArray = getPixelsSlow(sourceImage, quality, ignoreWhite);
        }

        // Send array to quantize function which clusters values using median
        // cut algorithm
        MMCQ.CMap cmap = MMCQ.quantize(pixelArray, colorCount);
        return cmap;
    }

private static int[][] getPixelsFast(BufferedImage sourceImage, int quality, boolean ignoreWhite) {
        DataBufferByte imageData = (DataBufferByte) sourceImage
                .getRaster()
                .getDataBuffer();
        byte[] pixels = imageData.getData();
        int pixelCount = sourceImage.getWidth() * sourceImage.getHeight();

        int colorDepth;
        int type = sourceImage.getType();
        switch (type) {
            case BufferedImage.TYPE_3BYTE_BGR:
                colorDepth = 3;
                break;

            case BufferedImage.TYPE_4BYTE_ABGR:
                colorDepth = 4;
                break;

            default:
                throw new IllegalArgumentException("Unhandled type: " + type);
        }

        int expectedDataLength = pixelCount * colorDepth;
        if (expectedDataLength != pixels.length) {
            throw new IllegalArgumentException("(expectedDataLength = "
                    + expectedDataLength + ") != (pixels.length = "
                    + pixels.length + ")");
        }

        // Store the RGB values in an array format suitable for quantize
        // function

        // numRegardedPixels must be rounded up to avoid an
        // ArrayIndexOutOfBoundsException if all pixels are good.
        int numRegardedPixels = (pixelCount + quality - 1) / quality;

        int numUsedPixels = 0;
        int[][] pixelArray = new int[numRegardedPixels][];
        int offset, r, g, b, a;

        // Do the switch outside of the loop, that's much faster
        switch (type) {
            case BufferedImage.TYPE_3BYTE_BGR:
                for (int i = 0; i < pixelCount; i += quality) {
                    offset = i * 3;
                    b = pixels[offset] & 0xFF;
                    g = pixels[offset + 1] & 0xFF;
                    r = pixels[offset + 2] & 0xFF;

                    // If pixel is not white
                    if (!(ignoreWhite && r > 250 && g > 250 && b > 250)) {
                        pixelArray[numUsedPixels] = new int[]{r, g, b};
                        numUsedPixels++;
                    }
                }
                break;

            case BufferedImage.TYPE_4BYTE_ABGR:
                for (int i = 0; i < pixelCount; i += quality) {
                    offset = i * 4;
                    a = pixels[offset] & 0xFF;
                    b = pixels[offset + 1] & 0xFF;
                    g = pixels[offset + 2] & 0xFF;
                    r = pixels[offset + 3] & 0xFF;

                    // If pixel is mostly opaque and not white
                    if (a >= 125 && !(ignoreWhite && r > 250 && g > 250 && b > 250)) {
                        pixelArray[numUsedPixels] = new int[]{r, g, b};
                        numUsedPixels++;
                    }
                }
                break;

            default:
                throw new IllegalArgumentException("Unhandled type: " + type);
        }

        // Remove unused pixels from the array
        return Arrays.copyOfRange(pixelArray, 0, numUsedPixels);
    }

private static int[][] getPixelsSlow(BufferedImage sourceImage, int quality, boolean ignoreWhite) {
        int width = sourceImage.getWidth();
        int height = sourceImage.getHeight();

        int pixelCount = width * height;

        // numRegardedPixels must be rounded up to avoid an
        // ArrayIndexOutOfBoundsException if all pixels are good.
        int numRegardedPixels = (pixelCount + quality - 1) / quality;

        int numUsedPixels = 0;

        int[][] res = new int[numRegardedPixels][];
        int r, g, b;

        for (int i = 0; i < pixelCount; i += quality) {
            int row = i / width;
            int col = i % width;
            int rgb = sourceImage.getRGB(col, row);

            r = (rgb >> 16) & 0xFF;
            g = (rgb >> 8) & 0xFF;
            b = (rgb) & 0xFF;
            if (!(ignoreWhite && r > 250 && r > 250 && r > 250)) {
                res[numUsedPixels] = new int[]{r, g, b};
                numUsedPixels++;
            }
        }

        return Arrays.copyOfRange(res, 0, numUsedPixels);
    }

public static double fastPerceptualColorDistanceSquared(int[] color1, int[] color2) {
        final int red1 = color1[0];
        final int red2 = color2[0];
        final int redMean = (red1 + red2) >> 1;
        final int r = red1 - red2;
        final int g = color1[1] - color2[1];
        final int b = color1[2] - color2[2];
        return (((512 + redMean) * r * r) >> 8) + 4 * g * g + (((767 - redMean) * b * b) >> 8);
    }

public static double slowPerceptualColorDistanceSquared(int[] color1, int[] color2) {
        final double colorDistance = fastPerceptualColorDistanceSquared(color1, color2);

        final double grey1 = (color1[0] + color1[1] + color1[2]) / 3;
        final double grey2 = (color2[0] + color2[1] + color2[2]) / 3;
        final double greyDistance1 = Math.abs(grey1 - color1[0]) + Math.abs(grey1 - color1[1]) + Math.abs(grey1 - color1[2]);
        final double greyDistance2 = Math.abs(grey2 - color2[0]) + Math.abs(grey2 - color2[1]) + Math.abs(grey2 - color2[2]);
        final double greyDistance = greyDistance1 - greyDistance2;

        return colorDistance + (greyDistance * greyDistance / 10.0);
    }

public static double slowPerceptualColorDistanceSquared(Color color1, Color color2) {
        final int[] colorInts1 = {color1.getRed(), color1.getGreen(), color1.getBlue()};
        final int[] colorInts2 = {color2.getRed(), color2.getGreen(), color2.getBlue()};
        return slowPerceptualColorDistanceSquared(colorInts1, colorInts2);
    }

static int getColorIndex(int r, int g, int b) {
        return (r << (2 * SIGBITS)) + (g << SIGBITS) + b;
    }

public VBox(int r1, int r2, int g1, int g2, int b1, int b2, int[] histo) {
            this.r1 = r1;
            this.r2 = r2;
            this.g1 = g1;
            this.g2 = g2;
            this.b1 = b1;
            this.b2 = b2;

            this.histo = histo;
        }

@Override
        public String toString() {
            return "r1: " + r1 + " / r2: " + r2 + " / g1: " + g1 + " / g2: "
                    + g2 + " / b1: " + b1 + " / b2: " + b2;
        }

public int volume(boolean force) {
            if (_volume == null || force) {
                _volume = ((r2 - r1 + 1) * (g2 - g1 + 1) * (b2 - b1 + 1));
            }

            return _volume;
        }

public int count(boolean force) {
            if (_count == null || force) {
                int npix = 0;
                int i, j, k, index;

                for (i = r1; i <= r2; i++) {
                    for (j = g1; j <= g2; j++) {
                        for (k = b1; k <= b2; k++) {
                            index = getColorIndex(i, j, k);
                            npix += histo[index];
                        }
                    }
                }

                _count = npix;
            }

            return _count;
        }

@Override
        public VBox clone() {
            return new VBox(r1, r2, g1, g2, b1, b2, histo);
        }

public int[] avg(boolean force) {
            if (_avg == null || force) {
                int ntot = 0;

                int rsum = 0;
                int gsum = 0;
                int bsum = 0;

                int hval, i, j, k, histoindex;

                for (i = r1; i <= r2; i++) {
                    for (j = g1; j <= g2; j++) {
                        for (k = b1; k <= b2; k++) {
                            histoindex = getColorIndex(i, j, k);
                            hval = histo[histoindex];
                            ntot += hval;
                            rsum += (hval * (i + 0.5) * MULT);
                            gsum += (hval * (j + 0.5) * MULT);
                            bsum += (hval * (k + 0.5) * MULT);
                        }
                    }
                }

                if (ntot > 0) {
                    _avg = new int[]{~~(rsum / ntot), ~~(gsum / ntot),
                            ~~(bsum / ntot)};
                } else {
                    _avg = new int[]{~~(MULT * (r1 + r2 + 1) / 2),
                            ~~(MULT * (g1 + g2 + 1) / 2),
                            ~~(MULT * (b1 + b2 + 1) / 2)};
                }
            }

            return _avg;
        }

public boolean contains(int[] pixel) {
            int rval = pixel[0] >> RSHIFT;
            int gval = pixel[1] >> RSHIFT;
            int bval = pixel[2] >> RSHIFT;

            return (rval >= r1 && rval <= r2 && gval >= g1 && gval <= g2
                    && bval >= b1 && bval <= b2);
        }

