@OnlyIn(Dist.CLIENT)
    private void spawnCloudParticles(PlayerEntity player) {
        Vector3 playerPos = Vector3.atEntityCorner(player).addY(0.1F);

        for (int i = 0; i < 3; i++) {
            float oX = (rand.nextFloat() - rand.nextFloat()) * 2F;
