                        return alphaIn;
                    }).andThen(VFXAlphaFunction.FADE_OUT))
                    .color(VFXColorFunction.WHITE)
                    .setScaleMultiplier(0.2F + rand.nextFloat() * 0.3F)
                    .setMaxAge(40 + rand.nextInt(20));
