        for (int i = 0; i < 3; i++) {
            Vector3 offset = MiscUtils.getRandomCirclePosition(new Vector3(), Vector3.RotAxis.Y_AXIS, 0.3F);
            float scale = 0.16F + rand.nextFloat() * 0.12F;
