@SubscribeEvent
    @OnlyIn(Dist.CLIENT)
    void onRender(RenderPlayerEvent.Post event) {
        PlayerEntity player = event.getPlayer();
        if (!shouldDoEffect(player)) {
            return;
        }
        MatrixStack renderStack = event.getMatrixStack();

        float rot = RenderingVectorUtils.interpolateRotation(player.prevRenderYawOffset, player.renderYawOffset, event.getPartialRenderTick());

        float yOffset = 1.2F;
        if (player.isSneaking() && !player.abilities.isFlying) {
            yOffset = 1F;
        }

        renderStack.push();

        float swimAngle = player.getSwimAnimation(event.getPartialRenderTick());
        if (swimAngle > 0) {
            float waterPitch = player.isInWater() ? -90.0F - player.rotationPitch : -90.0F;
            float bodySwimAngle = MathHelper.lerp(swimAngle, 0.0F, waterPitch);
            renderStack.rotate(Vector3f.YP.rotationDegrees(180 - rot));
            renderStack.rotate(Vector3f.XP.rotationDegrees(bodySwimAngle));
            if (player.isActualySwimming()) {
                renderStack.translate(0, -1, 0.3);
            }
        } else {
            renderStack.rotate(Vector3f.YP.rotationDegrees(180 - rot));
        }

        renderStack.translate(0, yOffset, 0);
        renderStack.scale(0.32F, 0.32F, 0.32F);

        RenderTypesAS.MODEL_WRAITH_WINGS.setupRenderState();

        renderStack.push();
        renderStack.translate(-2.3, 0, 0.8);
        renderStack.rotate(Vector3f.YP.rotationDegrees(10));
        ObjModelRender.renderWraithWings(renderStack);
        renderStack.pop();

        renderStack.push();
        renderStack.rotate(Vector3f.YP.rotationDegrees(180));
        renderStack.translate(-2.3, 0, -0.8);
        renderStack.rotate(Vector3f.YN.rotationDegrees(10));
        ObjModelRender.renderWraithWings(renderStack);
        renderStack.pop();

        RenderTypesAS.MODEL_WRAITH_WINGS.clearRenderState();

        renderStack.pop();
    }

@Override
    public TypeBlockRing buildEffect(UUID playerUUID, List<String> effectParameters) throws Exception {
        UUID effectUniqueId = UUID.fromString(effectParameters.get(0));
        FlareColor fc = null;
        if (!"null".equals(effectParameters.get(1))) {
            fc = FlareColor.valueOf(effectParameters.get(1));
        }

        float distance = Float.parseFloat(effectParameters.get(2));
        float rotationAngle = Float.parseFloat(effectParameters.get(3));
        int repeats = Integer.parseInt(effectParameters.get(4));
        int tickRotationSpeed = Integer.parseInt(effectParameters.get(5));
        JsonArray jo = (JsonArray) PARSER.parse(effectParameters.get(6));
        HashMap<BlockPos, BlockState> pattern = new HashMap<>();
        for (JsonElement patternElement : jo) {
            JsonObject obj = (JsonObject) patternElement;
            BlockPos pos = new BlockPos(
                    obj.getAsJsonPrimitive("posX").getAsInt(),
                    obj.getAsJsonPrimitive("posY").getAsInt(),
                    obj.getAsJsonPrimitive("posZ").getAsInt());
            Block b = ForgeRegistries.BLOCKS.getValue(new ResourceLocation(obj.getAsJsonPrimitive("block").getAsString()));
            pattern.put(pos, b.getDefaultState());
        }
        return new TypeBlockRing(effectUniqueId,
                fc, playerUUID,
                distance,
                rotationAngle,
                repeats,
                tickRotationSpeed,
                pattern);
    }

