    }

@Nullable
    public T getRandomElementChanced() {
        if (this.elements.isEmpty()) {
            return null;
        }
        float perc = 1F - (((float) this.getCount()) / this.maxAmount);
        perc = 0.1F / ((perc / 2F) + 0.1F);
        if (rand.nextFloat() < perc) {
            return getRandomElement();
