                    ((MobEntity) e).onInitialSpawn(world, world.getDifficultyForLocation(at), reason, null, null);
                    if (!((MobEntity) e).isNotColliding(world)) {
                        e.remove();
                        return;
                    }
                }
                world.addEntity(e);
                world.playEvent(2004, e.getPosition(), 0);
                world.playEvent(2004, e.getPosition(), 0);
            }
        }

