                    pos.getX() - 3   + rand.nextFloat() * 7,
                    pos.getY()       + rand.nextFloat(),
                    pos.getZ() - 3   + rand.nextFloat() * 7
            );
            Vector3 motion = particlePos.clone().vectorFromHereTo(at).normalize().divide(30);

