            recipe = mgr.getRecipes(IRecipeType.CRAFTING).values()
                    .stream()
                    .filter(r -> outputTest.test(r.getRecipeOutput()))
                    .findFirst()
                    .orElse(null);
            if (recipe != null) {
                return recipe;
            }
            return null;
        });
