                    .filter(r -> outputTest.test(r.getRecipeOutput()))
                    .findFirst()
                    .orElse(null);
            if (recipe != null) {
                return recipe;
            }

            recipe = mgr.getRecipes(RecipeTypesAS.TYPE_ALTAR.getType()).values()
                    .stream()
                    .map(r -> (SimpleAltarRecipe) r)
                    .filter(r -> outputTest.test(r.getOutputForRender(Collections.emptyList())))
                    .findFirst()
                    .orElse(null);
            if (recipe != null) {
                return recipe;
            }
            return null;
        });
    }

