private int getTotalAllocationCount() {
            int sum = 0;
            for (PerkAllocationType type : PerkAllocationType.values()) {
                sum += getAllocationCount(type);
            }
            return sum;
        }

private int getAllocationCount(PerkAllocationType type) {
            CompoundNBT metaData = this.getApplicationData();
            if (!metaData.contains(APPLICATION_KEYS, Constants.NBT.TAG_COMPOUND)) {
                return 0;
            }
            CompoundNBT applicationMeta = metaData.getCompound(APPLICATION_KEYS);
            ListNBT allocations = applicationMeta.getList(type.getSaveKey(), Constants.NBT.TAG_COMPOUND);
            return allocations.size();
        }

public boolean isAllocated(PerkAllocationType type) {
            return this.applicationTypes.contains(type);
        }

private PerkRemovalResult removeAllocation(PlayerPerkAllocation type, boolean simulate) {
            CompoundNBT metaData = this.getApplicationData();
            if (!metaData.contains(APPLICATION_KEYS, Constants.NBT.TAG_COMPOUND)) {
                return PerkRemovalResult.FAILURE;
            }
            CompoundNBT applicationMeta = metaData.getCompound(APPLICATION_KEYS);
            ListNBT allocations = applicationMeta.getList(type.getType().getSaveKey(), Constants.NBT.TAG_COMPOUND);
            if (allocations.isEmpty()) {
                return PerkRemovalResult.FAILURE;
            }

            boolean removedMatch = false;
            UUID removeUUID = type.getLockUUID();
            for (int i = 0; i < allocations.size(); i++) {
                CompoundNBT tag = allocations.getCompound(i);
                UUID lockUUID = tag.getUniqueId("uuid");
                if (lockUUID.equals(removeUUID)) {
                    if (!simulate) {
                        allocations.remove(i);
                    }
                    removedMatch = true;
                    break;
                }
            }
            if (!removedMatch) {
                return PerkRemovalResult.FAILURE;
            }

            if (simulate && allocations.size() <= 1) {
                if (this.applicationTypes.size() > 1) {
                    return PerkRemovalResult.REMOVE_ALLOCATION_TYPE;
                } else {
                    return PerkRemovalResult.REMOVE_PERK;
                }
            }
            if (allocations.isEmpty()) {
                this.applicationTypes.remove(type.getType());
                if (this.applicationTypes.isEmpty()) {
                    return PerkRemovalResult.REMOVE_PERK;
                }
                return PerkRemovalResult.REMOVE_ALLOCATION_TYPE;
            }
            return PerkRemovalResult.REMOVE_ALLOCATION;
        }

public boolean addAllocation(PlayerPerkAllocation type, boolean simulate) {
            if (!simulate) {
                this.applicationTypes.add(type.getType());
            }

            CompoundNBT metaData = this.getApplicationData();
            if (!metaData.contains(APPLICATION_KEYS, Constants.NBT.TAG_COMPOUND)) {
                if (simulate) {
                    return true;
                }
                metaData.put(APPLICATION_KEYS, new CompoundNBT());
            }
            CompoundNBT applicationMeta = metaData.getCompound(APPLICATION_KEYS);

            String key = type.getType().getSaveKey();
            if (!applicationMeta.contains(key, Constants.NBT.TAG_LIST)) {
                if (simulate) {
                    return true;
                }
                applicationMeta.put(key, new ListNBT());
            }
            ListNBT allocations = applicationMeta.getList(key, Constants.NBT.TAG_COMPOUND);

            UUID newUUID = type.getLockUUID();
            CompoundNBT newKeyTag = new CompoundNBT();
            newKeyTag.putUniqueId("uuid", newUUID);

            if (allocations.isEmpty()) {
                if (!simulate) {
                    allocations.add(newKeyTag);
                }
                return true;
            }
            for (int i = 0; i < allocations.size(); i++) {
                CompoundNBT tag = allocations.getCompound(i);
                UUID lockUUID = tag.getUniqueId("uuid");
                if (lockUUID.equals(newUUID)) {
                    return false;
                }
            }
            if (simulate) {
                return true;
            }
            return allocations.add(newKeyTag);
        }

public Set<PerkAllocationType> getApplicationTypes() {
            return this.applicationTypes;
        }

private CompoundNBT serialize() {
            CompoundNBT out = new CompoundNBT();
            out.putString("perk", this.perk.getRegistryName().toString());
            out.put("perkData", this.perkData);
            out.put("applicationData", this.applicationData);
            int[] types = this.applicationTypes.stream()
                    .mapToInt(Enum::ordinal)
                    .toArray();
            out.putIntArray("applicationTypes", types);
            return out;
        }

private static Optional<AppliedPerk> deserialize(CompoundNBT tag) {
            ResourceLocation key = new ResourceLocation(tag.getString("perk"));
            return PerkTree.PERK_TREE.getPerk(LogicalSide.SERVER, key)
                    .map(AppliedPerk::new)
                    .map(appliedPerk -> {
                        appliedPerk.perkData = tag.getCompound("perkData");
                        appliedPerk.applicationData = tag.getCompound("applicationData");
                        int[] types = tag.getIntArray("applicationTypes");
                        appliedPerk.applicationTypes = IntStream.of(types)
                                .mapToObj(type -> PerkAllocationType.values()[type])
                                .collect(Collectors.toSet());
                        return appliedPerk;
                    });
        }

private void write(PacketBuffer buf) {
            ByteBufUtils.writeNBTTag(buf, this.perkData);
            ByteBufUtils.writeNBTTag(buf, this.applicationData);
            ByteBufUtils.writeCollection(buf, this.applicationTypes, ByteBufUtils::writeEnumValue);
        }

private void read(PacketBuffer buf) {
            this.perkData = ByteBufUtils.readNBTTag(buf);
            this.applicationData = ByteBufUtils.readNBTTag(buf);
            this.applicationTypes = ByteBufUtils.readSet(buf, buffer -> ByteBufUtils.readEnumValue(buffer, PerkAllocationType.class));
        }

@Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            AppliedPerk that = (AppliedPerk) o;
            return Objects.equals(perk.getRegistryName(), that.perk.getRegistryName());
        }

@Override
        public int hashCode() {
            return Objects.hash(perk.getRegistryName());
        }

public void load(CompoundNBT compound) {
        knownConstellations.clear();
        seenConstellations.clear();
        researchProgression.clear();
        storedConstellationPapers.clear();
        attunedConstellation = null;
        tierReached = ProgressionTier.DISCOVERY;
        wasOnceAttuned = false;
        tomeReceived = false;
        usePerkAbilities = true;

        if (compound.contains("seenConstellations")) {
            ListNBT list = compound.getList("seenConstellations", Constants.NBT.TAG_STRING);
            for (int i = 0; i < list.size(); i++) {
                seenConstellations.add(new ResourceLocation(list.getString(i)));
            }
        }
        if (compound.contains("constellations")) {
            ListNBT list = compound.getList("constellations", Constants.NBT.TAG_STRING);
            for (int i = 0; i < list.size(); i++) {
                ResourceLocation s = new ResourceLocation(list.getString(i));
                knownConstellations.add(s);
                if (!seenConstellations.contains(s)) {
                    seenConstellations.add(s);
                }
            }
        }
        if (compound.contains("storedConstellationPapers")) {
            ListNBT list = compound.getList("storedConstellationPapers", Constants.NBT.TAG_STRING);
            for (int i = 0; i < list.size(); i++) {
                ResourceLocation s = new ResourceLocation(list.getString(i));
                storedConstellationPapers.add(s);
                if (!seenConstellations.contains(s)) {
                    seenConstellations.add(s);
                }
            }
        }

        if (compound.contains("attuned")) {
            String cst = compound.getString("attuned");
            IConstellation c = ConstellationRegistry.getConstellation(new ResourceLocation(cst));
            if (!(c instanceof IMajorConstellation)) {
                AstralSorcery.log.warn("Failed to load attuned Constellation: " + cst + " - constellation doesn't exist or isn't major.");
            } else {
                attunedConstellation = (IMajorConstellation) c;
            }
        }

        this.perkData.load(this, compound);

        if (compound.contains("tierReached")) {
            int tierOrdinal = compound.getInt("tierReached");
            tierReached = MiscUtils.getEnumEntry(ProgressionTier.class, tierOrdinal);
        }

        if (compound.contains("research")) {
            int[] research = compound.getIntArray("research");
            for (int resOrdinal : research) {
                researchProgression.add(MiscUtils.getEnumEntry(ResearchProgression.class, resOrdinal));
            }
        }

        this.wasOnceAttuned = compound.getBoolean("wasAttuned");


        if (!compound.contains("bookReceived")) {
            this.tomeReceived = true; //Legacy support for player progress files that do not have the tag yet.
        } else {
            this.tomeReceived = compound.getBoolean("bookReceived");
        }

        if (compound.contains("usePerkAbilities")) {
            this.usePerkAbilities = compound.getBoolean("usePerkAbilities");
        }
    }

public void store(CompoundNBT cmp) {
        ListNBT known = new ListNBT();
        for (ResourceLocation s : knownConstellations) {
            known.add(StringNBT.valueOf(s.toString()));
        }
        ListNBT seen = new ListNBT();
        for (ResourceLocation s : seenConstellations) {
            seen.add(StringNBT.valueOf(s.toString()));
        }
        ListNBT storedPapers = new ListNBT();
        for (ResourceLocation s : storedConstellationPapers) {
            storedPapers.add(StringNBT.valueOf(s.toString()));
        }
        cmp.put("constellations", known);
        cmp.put("seenConstellations", seen);
        cmp.put("storedConstellationPapers", storedPapers);
        cmp.putInt("tierReached", tierReached.ordinal());
        cmp.putBoolean("wasAttuned", wasOnceAttuned);
        int[] researchArray = researchProgression.stream()
                .mapToInt(ResearchProgression::ordinal)
                .toArray();
        cmp.putIntArray("research", researchArray);
        if (attunedConstellation != null) {
            cmp.putString("attuned", attunedConstellation.getRegistryName().toString());
        }
        PerkTree.PERK_TREE.getVersion(LogicalSide.SERVER).ifPresent(version -> cmp.putLong("perkTreeVersion", version));

        cmp.putBoolean("bookReceived", tomeReceived);
        cmp.putBoolean("usePerkAbilities", usePerkAbilities);

        this.perkData.save(cmp);
    }

public void storeKnowledge(CompoundNBT cmp) {
        ListNBT list = new ListNBT();
        for (ResourceLocation s : knownConstellations) {
            list.add(StringNBT.valueOf(s.toString()));
        }
        ListNBT l = new ListNBT();
        for (ResourceLocation s : seenConstellations) {
            l.add(StringNBT.valueOf(s.toString()));
        }
        cmp.put("constellations", list);
        cmp.put("seenConstellations", l);
        cmp.putInt("tierReached", tierReached.ordinal());
        cmp.putBoolean("wasAttuned", wasOnceAttuned);
        int[] researchArray = researchProgression.stream()
                .mapToInt(ResearchProgression::ordinal)
                .toArray();
        cmp.putIntArray("research", researchArray);
    }

public void loadKnowledge(CompoundNBT compound) {
        if (compound.contains("seenConstellations")) {
            ListNBT list = compound.getList("seenConstellations", Constants.NBT.TAG_STRING);
            for (int i = 0; i < list.size(); i++) {
                ResourceLocation cstName = new ResourceLocation(list.getString(i));
                if (!seenConstellations.contains(cstName)) {
                    seenConstellations.add(cstName);
                }
            }
        }
        if (compound.contains("constellations")) {
            ListNBT list = compound.getList("constellations", Constants.NBT.TAG_STRING);
            for (int i = 0; i < list.size(); i++) {
                ResourceLocation cstName = new ResourceLocation(list.getString(i));

                if (!knownConstellations.contains(cstName)) {
                    knownConstellations.add(cstName);
                }
                if (!seenConstellations.contains(cstName)) {
                    seenConstellations.add(cstName);
                }
            }
        }

        if (compound.contains("tierReached")) {
            int tierOrdinal = compound.getInt("tierReached");
            ProgressionTier otherTier = MiscUtils.getEnumEntry(ProgressionTier.class, tierOrdinal);
            if (otherTier.isThisLater(this.tierReached)) {
                this.tierReached = otherTier;
            }
        }

        if (compound.contains("research")) {
            int[] research = compound.getIntArray("research");
            for (int resOrdinal : research) {
                researchProgression.add(MiscUtils.getEnumEntry(ResearchProgression.class, resOrdinal));
            }
        }
    }

