@Override
    public void onServerStart() {
        reset();

        saveTask = new TimerTask() {
            @Override
            public void run() {
                instance.doSave();
            }
        };
        timer = new Timer("ResearchIOThread", true);
        timer.scheduleAtFixedRate(saveTask, 30_000, 30_000);
    }

@Override
            public void run() {
