            AdvancementsAS.DISCOVER_CONSTELLATION.trigger((ServerPlayerEntity) player, cst);
        }

        ResearchSyncHelper.pushProgressToClientUnsafe(progress, player);
        ResearchHelper.savePlayerKnowledge(player);
        return true;
    }

