@Nullable
    public static AmuletEnchantment deserialize(CompoundNBT cmp) {
        int typeId = cmp.getInt("type");
        DynamicEnchantmentType type = DynamicEnchantmentType.values()[typeId];
        int level = Math.max(0, cmp.getInt("level"));
        if (type.isEnchantmentSpecific()) {
            ResourceLocation res = new ResourceLocation(cmp.getString("ench"));
            Enchantment e = ForgeRegistries.ENCHANTMENTS.getValue(res);
            if (e != null) {
                return new AmuletEnchantment(type, e, level);
            }
        } else {
            return new AmuletEnchantment(type, level);
        }
        return null;
    }

public static void removeAmuletTagsAndCleanup(PlayerEntity player, boolean keepEquipped) {
        PlayerInventory inv = player.inventory;
        for (int i = 0; i < inv.mainInventory.size(); i++) {
            if (i == inv.currentItem && keepEquipped) {
                continue;
            }
            removeAmuletOwner(inv.mainInventory.get(i));
        }
        removeAmuletOwner(inv.getItemStack());
        if (!keepEquipped) {
            for (int i = 0; i < inv.armorInventory.size(); i++) {
                removeAmuletOwner(inv.armorInventory.get(i));
            }
            for (int i = 0; i < inv.offHandInventory.size(); i++) {
                removeAmuletOwner(inv.offHandInventory.get(i));
            }
        }
    }

