@Nullable
    public static PlayerEntity getPlayerHavingTool(ItemStack anyTool) {
        UUID plUUID = getWornPlayerUUID(anyTool);
        if (plUUID.getLeastSignificantBits() == 0 && plUUID.getMostSignificantBits() == 0) {
            return null;
        }
        PlayerEntity player;
        if (EffectiveSide.get() == LogicalSide.CLIENT) {
            player = resolvePlayerClient(plUUID);
        } else {
            MinecraftServer server = LogicalSidedProvider.INSTANCE.get(LogicalSide.SERVER);
            if (server == null) {
                return null;
            }
            player = server.getPlayerList().getPlayerByUUID(plUUID);
        }
        if (player == null) {
            return null;
        }

        int originalDamage = anyTool.getDamage(); //Save the original damage on the tool

        //Check if the player actually wears/carries the tool
        boolean foundTool = false;
        for (EquipmentSlotType slot : EquipmentSlotType.values()) {
            ItemStack stack = player.getItemStackFromSlot(slot);
            anyTool.setDamage(stack.getDamage()); //Make sure the damages are equal before comparing
            if (ItemComparator.compare(stack, anyTool, ItemComparator.Clause.Sets.ITEMSTACK_STRICT)) {
                foundTool = true;
                break;
            }
        }
        anyTool.setDamage(originalDamage); //Reset original damage on the tool
        if (!foundTool) return null;

        return player;
    }

@Nullable
    static Tuple<ItemStack, PlayerEntity> getWornAmulet(ItemStack anyTool) {
        PlayerEntity player = getPlayerHavingTool(anyTool);
        if (player == null) return null;

        Optional<ImmutableTriple<String, Integer, ItemStack>> curios =
                IntegrationCurios.getCurio(player, (stack) -> stack.getItem() instanceof ItemEnchantmentAmulet);
        return curios.map(trpl -> new Tuple<>(trpl.right, player)).orElse(null);
    }

@OnlyIn(Dist.CLIENT)
    private static PlayerEntity resolvePlayerClient(UUID plUUID) {
        Optional<World> w = LogicalSidedProvider.CLIENTWORLD.get(LogicalSide.CLIENT);
        return w.map(world -> world.getPlayerByUuid(plUUID)).orElse(null);
    }

public static void rollAmulet(ItemStack stack) {
        if (stack.isEmpty() || !(stack.getItem() instanceof ItemEnchantmentAmulet)) {
            return;
        }

        List<AmuletEnchantment> ench = new ArrayList<>();
        while (mayGetAdditionalRoll(ench)) {
            DynamicEnchantmentType type = getRollType(ench);
            if (type != null) {
                int lvl = getRollLevel();
                if (type.isEnchantmentSpecific()) {
                    Enchantment e = AmuletEnchantmentRegistry.getRandomEnchant();
                    if (e != null) {
                        ench.add(new AmuletEnchantment(type, e, lvl));
                    }
                } else {
                    ench.add(new AmuletEnchantment(type, lvl));
                }
            }
        }
        ItemEnchantmentAmulet.setAmuletEnchantments(stack, collapseEnchantments(ench));
    }

@Nullable
    private static DynamicEnchantmentType getRollType(List<AmuletEnchantment> existing) {
        int exAll = getAdditionAll(existing);
        switch (existing.size()) {
            case 0:
            case 1:
                if (rand.nextFloat() < chanceToAll.get()) {
                    return DynamicEnchantmentType.ADD_TO_EXISTING_ALL;
                }
                if (rand.nextFloat() < chanceToNonExisting.get()) {
                    return DynamicEnchantmentType.ADD_TO_SPECIFIC;
                }
                return DynamicEnchantmentType.ADD_TO_EXISTING_SPECIFIC;
            case 2:
                if (exAll > 1) {
                    return null;
                } else if (exAll == 1) {
                    if (rand.nextFloat() < chanceToNonExisting.get()) {
                        return DynamicEnchantmentType.ADD_TO_SPECIFIC;
                    }
                    return DynamicEnchantmentType.ADD_TO_EXISTING_SPECIFIC;
                } else {
                    if (rand.nextFloat() < chanceToAll.get()) {
                        return DynamicEnchantmentType.ADD_TO_EXISTING_ALL;
                    }
                    if (rand.nextFloat() < chanceToNonExisting.get()) {
                        return DynamicEnchantmentType.ADD_TO_SPECIFIC;
                    }
                    return DynamicEnchantmentType.ADD_TO_EXISTING_SPECIFIC;
                }
            default:
                break;
        }
        return null;
    }

private static int getRollLevel() {
        if (rand.nextFloat() < chance2Level.get()) {
            return 2;
        }
        return 1;
    }

private static boolean mayGetAdditionalRoll(List<AmuletEnchantment> existing) {
        if (existing.isEmpty()) return true;
        switch (existing.size()) {
            case 1:
                return rand.nextFloat() < chance2nd.get();
            case 2:
                return getAdditionAll(existing) < 2 && rand.nextFloat() < chance3rd.get();
            default:
                break;
        }
        return false;
    }

private static int getAdditionAll(List<AmuletEnchantment> ench) {
        int i = 0;
        for (AmuletEnchantment e : ench) {
            if (e.getType().equals(DynamicEnchantmentType.ADD_TO_EXISTING_ALL)) {
                i++;
            }
        }
        return i;
    }

private static List<AmuletEnchantment> collapseEnchantments(List<AmuletEnchantment> ench) {
        List<AmuletEnchantment> enchantments = new LinkedList<>();
        for (AmuletEnchantment e : ench) {
            boolean found = false;
            for (AmuletEnchantment ex : enchantments) {
                if (ex.canMerge(e)) {
                    ex.merge(e);
                    found = true;
                    break;
                }
            }
            if (!found) {
                enchantments.add(e);
            }
        }
        return enchantments;
    }

