        if (color.isPresent()) {
            return color.get();
        }
        int tick = (int) (ClientScheduler.getClientTick() % 500000L);
        int c = Color.getHSBColor(tick / 500000F, 0.7F, 1F).getRGB();
        return c | 0xFF000000;
