private void onEnchantmentAddServer(DynamicEnchantmentEvent.Add event) {
        PlayerEntity player = event.getResolvedPlayer();
        LogicalSide side = this.getSide(player);
        if (side.isServer()) {
            addEnchantments(player, side, event);
