        if (rand.nextInt(4) == 0) {
            EffectHelper.of(EffectTemplatesAS.GENERIC_PARTICLE)
                    .spawn(new Vector3(this)
                            .add(rand.nextFloat(), rand.nextFloat(), rand.nextFloat()))
                    .alpha(VFXAlphaFunction.FADE_OUT)
                    .color(VFXColorFunction.WHITE)
