@Override
    protected BlockPos genNext(Vector3 offset, double radius) {
        if (radius <= 0) {
            return offset.toBlockPos();
        }
        return offset.clone().add(Vector3.random().multiply(radius)).toBlockPos();
    }

@Override
    protected BlockPos genNext(Vector3 offset, double radius) {
        BlockPos next1 = super.genNext(offset, radius);
        BlockPos next2 = super.genNext(offset, radius);
        return offset.distance(next1) < offset.distance(next2) ? next1 : next2;
    }

@Override
    public BlockPos genNext(Vector3 offset, double radius) {
        if (this.currentRadius > radius) {
            this.currentPositions.clear();
        }

        while (currentPositions.isEmpty()) {
            generatePositions(radius);
        }
        return offset.add(currentPositions.remove(0)).toBlockPos();
    }

private void generatePositions(double maxRadius) {
        if (maxRadius <= 0) {
            this.currentPositions.add(BlockPos.ZERO);
            return;
        }
        if (this.currentRadius >= maxRadius || this.currentRadius < 0) {
            this.currentRadius = 0;
        }
        this.currentRadius++;

        this.currentPositions.addAll(BlockGeometry.getHollowSphere(this.currentRadius, this.currentRadius - 1));
        Collections.shuffle(this.currentPositions, new Random(0xF518E23A05B27C19L));
    }

@Override
    public void writeToNBT(CompoundNBT nbt) {
        nbt.putInt("currentRadius", this.currentRadius);
    }

@Override
    public void readFromNBT(CompoundNBT nbt) {
        this.currentRadius = nbt.getInt("currentRadius");
    }

public static boolean onCollision(VoxelShapeSpliterator iterator, Consumer<? super VoxelShape> action) {
        if (!CollisionManager.needsCustomCollision(iterator.entity)) {
            return false;
        }
        AxisAlignedBB box = CollisionManager.getIteratorBoundingBoxes(iterator, iterator.entity);
        if (box == null) {
            return false;
        }

        VoxelShape floor = VoxelShapes.create(box);
        if (VoxelShapes.compare(floor, VoxelShapes.create(iterator.aabb.grow(1.0E-7D)), IBooleanFunction.AND)) {
            action.accept(floor);
            return true;
        }
        return false;
    }

@Nullable
    public static Vector3d onEntityCollision(Vector3d allowedMovement, Entity entity) {
        if (!CollisionManager.needsCustomCollision(entity)) {
            return null;
        }
        List<AxisAlignedBB> additionalBoxes = CollisionManager.getAdditionalBoundingBoxes(entity);
        AxisAlignedBB entityBox = entity.getBoundingBox().grow(1.0E-7D);
        for (AxisAlignedBB box : additionalBoxes) {
            double newYMovement = VoxelShapes.create(box).getAllowedOffset(Direction.Axis.Y, entityBox, allowedMovement.y);
            allowedMovement = new Vector3d(allowedMovement.x, newYMovement, allowedMovement.z);
        }

        return allowedMovement;
    }

public static void init() {
        register(new MantleEffectAevitas.PlayerWalkableAir());
    }

public static void register(CustomCollisionHandler handler) {
        customHandlers.add(handler);
    }

@Nullable
    public static AxisAlignedBB getIteratorBoundingBoxes(VoxelShapeSpliterator iterator, @Nullable Entity entity) {
        if (!instanceFlags.containsKey(iterator)) {
            List<AxisAlignedBB> additionalBoundingBoxes = getAdditionalBoundingBoxes(entity);
            if (additionalBoundingBoxes.isEmpty()) {
                return null;
            }
            removeOldestEntry();
            instanceFlags.put(iterator, additionalBoundingBoxes);
            accessList.addFirst(iterator);
        }
        List<AxisAlignedBB> boxes = instanceFlags.get(iterator);
        if (boxes == null || boxes.isEmpty()) {
            return null;
        }
        markActive(iterator);
        return boxes.remove(0);
    }

public static boolean needsCustomCollision(@Nullable Entity entity) {
        for (CustomCollisionHandler handler : customHandlers) {
            if (handler.shouldAddCollisionFor(entity)) {
                return true;
            }
        }
        return false;
    }

public static List<AxisAlignedBB> getAdditionalBoundingBoxes(@Nullable Entity entity) {
        List<AxisAlignedBB> additionalCollision = new ArrayList<>();
        AxisAlignedBB entityBox = entity != null ? entity.getBoundingBox() : new AxisAlignedBB(BlockPos.ZERO);
        customHandlers.stream()
                .filter(handler -> handler.shouldAddCollisionFor(entity))
                .forEach(handler -> handler.addCollision(entity, entityBox, additionalCollision));
        return additionalCollision;
    }

private static void removeOldestEntry() {
        if (accessList.size() >= maxCacheSize) {
            VoxelShapeSpliterator oldest;
            //Apparently the list can be both >= 20 elements in size AND empty at the same time.
            try {
                oldest = accessList.removeLast();
            } catch (NoSuchElementException exc) {
                if (accessList.isEmpty()) {
                    return;
                }
                try {
                    oldest = accessList.get(accessList.size() - 1);
                } catch (Exception e) {
                    return;
                }
            }
            if (oldest != null) {
                instanceFlags.remove(oldest);
            }
        }
    }

private static void markActive(VoxelShapeSpliterator it) {
        if (accessList.remove(it)) {
            accessList.addFirst(it);
        }
    }

