@Inject(
            method = "processUseEntity",
            at = @At(value = "INVOKE", target = "Lnet/minecraft/network/play/ServerPlayNetHandler;disconnect(Lnet/minecraft/util/text/ITextComponent;)V"),
            cancellable = true
    )
    public void allowInteractableEntity(CUseEntityPacket packet, CallbackInfo ci) {
        ServerWorld world = this.player.getServerWorld();
        Entity interacted = packet.getEntityFromWorld(world);
        if (interacted instanceof InteractableEntity) {
            this.player.attackTargetEntityWithCurrentItem(interacted);
            ci.cancel();
        }
    }

@Inject(method = "tryAdvance", at = @At("HEAD"), cancellable = true)
    public void addCustomCollision(Consumer<? super VoxelShape> collisionShapeIterator, CallbackInfoReturnable<Boolean> cir) {
        if (!this.astralSorceryDidCustomCollision) {
            VoxelShapeSpliterator iterator = (VoxelShapeSpliterator)(Object) this;
            if (CollisionHelper.onCollision(iterator, collisionShapeIterator)) {
                cir.setReturnValue(true);
                return;
            }
            this.astralSorceryDidCustomCollision = true;
        }
    }

@Inject(method = "calculateInitialSkylight", at = @At("RETURN"), cancellable = true)
    public void solarEclipseSunBrightnessServer(CallbackInfo ci) {
        World world = (World)(Object) this;

        WorldContext ctx = SkyHandler.getContext(world);
        String strDimKey = world.getDimensionKey().getLocation().toString();
        if (ctx != null &&
                ctx.getCelestialEventHandler().getSolarEclipse().isActiveNow()) {
            this.skylightSubtracted = 11 - Math.round(ctx.getCelestialEventHandler().getSolarEclipsePercent() * 11F);
        }
    }

@Inject(method = "getSunBrightness", at = @At("RETURN"), cancellable = true)
    public void solarEclipseSunBrightness(float partialTicks, CallbackInfoReturnable<Float> cir) {
        World world = (World)(Object) this;

        WorldContext ctx = SkyHandler.getContext(world, LogicalSide.CLIENT);
        String strDimKey = world.getDimensionKey().getLocation().toString();
        if (ctx != null &&
                RenderingConfig.CONFIG.dimensionsWithSkyRendering.get().contains(strDimKey) &&
                ctx.getCelestialEventHandler().getSolarEclipse().isActiveNow()) {
            float perc = ctx.getCelestialEventHandler().getSolarEclipsePercent();
            perc = 0.05F + (perc * 0.95F);

            cir.setReturnValue(cir.getReturnValueF() * perc);
        }
    }

@ModifyConstant(method = "getMouseOver", constant = @Constant(intValue = 1, ordinal = 0), require = 1)
    public int adjustDistanceCheck(int flagDoDistanceCheck) {
        PlayerProgress prog = ResearchHelper.getProgress(Minecraft.getInstance().player, LogicalSide.CLIENT);
        if (prog.isValid() && prog.getPerkData().hasPerkEffect(perk -> perk instanceof KeyEntityReach)) {
            return 0;
        }
        return flagDoDistanceCheck;
    }

@Inject(method = "getTooltip", at = @At(value = "INVOKE", target = "Lnet/minecraft/item/ItemStack;hasTag()Z", ordinal = 0), locals = LocalCapture.CAPTURE_FAILSOFT)
    public void addMissingEnchantmentTooltip(PlayerEntity player, ITooltipFlag advanced, CallbackInfoReturnable<List<ITextComponent>> cir, List<ITextComponent> tooltip) {
        ItemStack stack = (ItemStack)(Object) this;

        List<ITextComponent> addition = new ArrayList<>();
        try {
            //Add any dynamic modifiers this item has.
            DynamicModifierHelper.addModifierTooltip(stack, addition);

            //Add prism enchantments
            Map<Enchantment, Integer> enchantments;
            if (!stack.hasTag() && !(enchantments = EnchantmentHelper.getEnchantments(stack)).isEmpty()) {
                for (Enchantment e : enchantments.keySet()) {
                    addition.add(e.getDisplayName(enchantments.get(e)));
                }
            }
        } catch (Exception exc) {
            addition.clear();
            tooltip.add(new TranslationTextComponent("astralsorcery.misc.tooltipError").mergeStyle(TextFormatting.GRAY));
        }
        tooltip.addAll(addition);
    }

@Redirect(method = "getTooltip", at = @At(value = "INVOKE", target = "Lnet/minecraft/item/ItemStack;getEnchantmentTagList()Lnet/minecraft/nbt/ListNBT;"))
    public ListNBT enhanceEnchantmentTooltip(ItemStack stack) {
        return DynamicEnchantmentHelper.modifyEnchantmentTags(stack.getEnchantmentTagList(), stack);
    }

@Inject(
            method = "renderParticles(Lcom/mojang/blaze3d/matrix/MatrixStack;Lnet/minecraft/client/renderer/IRenderTypeBuffer$Impl;Lnet/minecraft/client/renderer/LightTexture;Lnet/minecraft/client/renderer/ActiveRenderInfo;FLnet/minecraft/client/renderer/culling/ClippingHelper;)V",
            at = @At("RETURN"),
            remap = false
    )
    public void renderParticles(MatrixStack matrixStack, IRenderTypeBuffer.Impl buffer, LightTexture lightTexture, ActiveRenderInfo ari, float pTicks, ClippingHelper clippingHelper, CallbackInfo ci) {
        EffectHandler.getInstance().render(matrixStack, pTicks);

        //Setup GL states again
        //Seriously, keep a clean GL state for once mojang.
        RenderSystem.enableAlphaTest();
        RenderSystem.blendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA,
                GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
        GlStateManager.enableDepthTest();
        GlStateManager.enableTexture();
    }
